level_id = #{levelId}, benefit_name = #{benefitName}, benefit_type = #{benefitType}, benefit_value = #{benefitValue}, description = #{description}, shelf_status = #{shelfStatus}, goods_id = #{goodsId}, school_id = #{schoolId}, department = #{department}, claim_type = #{claimType}, benefit_category = #{benefitCategory}, use_url = #{useUrl}, status = #{status}, update_time = NOW(),
